/**
 * Emits byte-exact ABI test vectors for every SPAWN! message op, generated by
 * the SAME coder the EVM contracts use (ethers AbiCoder ≡ solc abi.encode),
 * from the shapes in scripts/lib-wire.js — the one place the tooling encodes
 * the wire. The Solana codec must round-trip each vector bit-for-bit — that
 * is the cross-chain contract.
 *
 * PROTOCOL v7.2 (second round): BUY and SELL carry the trader's minimum as a
 * fourth word; OPEN (6) and MOVE (7) are new; the adapter envelope ends with
 * the reply budget the message must arrive with.
 *
 * WIRE CONVENTION (protocol v4): every account rider is a `bytes32`. EVM
 * addresses ride left-padded; 32-byte chains (Solana) ride raw pubkeys.
 * Vectors flagged `wide: true` carry riders whose top 12 bytes are NOT zero:
 * the Solana codec must accept them verbatim, while an EVM receiver must
 * revert ("PAD: bad recipient" / "GW: bad recipient") when it would consume
 * them as an `address` — that revert is proven in the hardhat suite.
 *
 *   npx hardhat run scripts/gen-codec-vectors.js
 *   VECTORS_OUT=path.json npx hardhat run scripts/gen-codec-vectors.js
 *
 * WHERE IT WRITES: solana/tests/codec-vectors-v72.gen.json (not
 * solana/tests/codec-vectors.json: the Solana suites still read that file as
 * the PRE-v7.2 vectors and assert its old BUY / SELL / envelope shapes are
 * refused; moving them onto this file is the Solana side's change to make).
 * It also CROSS-CHECKS the hand-written solana/tests/codec-vectors-v72.json
 * against this coder, word by word, and exits 1 on any difference.
 */
const fs = require('fs')
const path = require('path')
const { zeroPadValue, solidityPacked } = require('ethers')
const { coder, OPS, encodeOp, encodeEnvelope } = require('./lib-wire')

const env = (op, types, values) =>
  coder.encode(['uint8', 'bytes'], [op, coder.encode(types, values)])

const pad32 = (a) => zeroPadValue(a, 32)
const B0 = pad32('0x0000000000000000000000000000000000000000')
const B1 = pad32('0x1111111111111111111111111111111111111111')
const BMAX = pad32('0xffffffffffffffffffffffffffffffffffffffff')
const PAD = pad32('0xcA6b51B8760EC432070cE356345c3ea9489f61Bd')
const TOK = pad32('0x8b7240CDE08F02CAb803974cA8aA04af5E81e56c')
// Solana-shaped riders: all 32 bytes in use — legal on the wire, EVM-unrepresentable.
const SOL1 = '0x' + '05'.repeat(32)
const SOLMAX = '0x' + 'ff'.repeat(32)
const U256_MAX = (1n << 256n) - 1n
const E18 = 10n ** 18n

// [name, values, wide?]
const CASES = [
  ['SPAWN', [B1, 'OMNI TEST', 'OMNI', '{"smoke":true}', 0n, 1]],
  ['SPAWN', [PAD, '', '', '', U256_MAX, 3]],
  // >32-byte strings exercise multi-word tails; unicode exercises UTF-8 length vs char count
  ['SPAWN', [BMAX, 'a name that is much longer than thirty-two bytes, yes indeed', '🔥🚀', 'x'.repeat(95), 5n * E18, 0]],
  ['SPAWN', [SOL1, 'SOLANA BORN', 'SOL', '{"home":"devnet"}', 2n * E18, 2], true],
  ['BUY', [TOK, B1, 5n * E18, 0n]],
  ['BUY', [B0, BMAX, 1n, U256_MAX]],
  ['BUY', [TOK, SOL1, 7n * E18, 1_000_000n * E18], true],
  ['SELL', [TOK, PAD, 884495291384607698648615n, 3n * E18]],
  ['SELL', [B1, B1, 0n, 0n]],
  ['SELL', [TOK, SOLMAX, 42n * E18, 1n], true],
  // v7.2: a chain asks for a token's replica; a claim moves to another chain
  ['OPEN', [TOK]],
  ['OPEN', [B0]],
  ['MOVE', [B1, PAD, 5n * E18, 4]],
  ['MOVE', [SOL1, B1, 1n, 3], true],
  ['MOVE', [B1, SOLMAX, U256_MAX, 1], true],
  ['CLAIM', [TOK, B1]],
  ['CLAIM', [B0, B0]],
  ['CLAIM', [TOK, SOL1], true],
  ['PULL_FEES', [TOK]],
  ['PULL_FEES', [B0]],
  ['PULL_FEES', [BMAX]],
  // the largest spawn a gateway admits (64 / 16 / 1024 bytes) — what the hub-bound gas must cover
  ['SPAWN', [SOLMAX, 'N'.repeat(64), 'S'.repeat(16), 'm'.repeat(1024), 250n * E18, 3], true],
  ['SYNC_TOKEN', [TOK, 'OMNI TEST', 'OMNI']],
  ['SYNC_TOKEN', [B1, 'thirty-two bytes exactly roight!', 'S']],
  ['SYNC_TOKEN', [BMAX, '', '']],
  ['DELIVER', [TOK, B1, 884495291384607698648615n, 0n]],
  ['DELIVER', [TOK, BMAX, U256_MAX, 123456789n * E18]],
  ['DELIVER', [B0, B0, 1n, 1n]],
  ['DELIVER', [TOK, SOL1, 1_000_000n * E18, 5n * E18], true],
  ['PAYOUT', [B1, 4n * E18 + 999_999_999_999n]],
  ['PAYOUT', [BMAX, U256_MAX]],
  ['PAYOUT', [SOLMAX, 9n * E18], true],
  ['FEE_DROP', [TOK, 2n * E18]],
  ['FEE_DROP', [B0, 0n]],
]

const vectors = CASES.map(([name, values, wide], i) => {
  const { op, types } = OPS[name]
  return {
    idx: i,
    name,
    op,
    wide: !!wide,
    inner: values.map((v, j) =>
      types[j] === 'uint256' ? '0x' + v.toString(16).padStart(64, '0') : typeof v === 'bigint' ? v.toString() : v,
    ),
    types,
    hex: env(op, types, values),
  }
})

// ADAPTER ENVELOPE (v5, v7.2): between transports every message rides as
// abi.encode(bytes32 srcSender, bytes32 dstAddr, bytes payload, uint256
// value) — wide on both seats so a Solana OApp store can be sender or
// target; `value` is the reply budget the receiving adapter requires the
// delivery to bring (msg.value >= value).
const STORE = '0x' + '42'.repeat(32) // a Solana-shaped OApp store id
const ENVELOPES = [
  // hub pad -> Solana store: a DELIVER to a wide recipient (a reply: no budget)
  { name: 'ENV_PAD_TO_STORE', src: PAD, dst: STORE, value: 0n, payload: vectors.find((v) => v.name === 'DELIVER' && v.wide).hex },
  // Solana store -> hub pad: a BUY from a wide buyer, one reply leg prepaid
  { name: 'ENV_STORE_TO_PAD', src: STORE, dst: PAD, value: 200_000_000_000_000n, payload: vectors.find((v) => v.name === 'BUY' && v.wide).hex },
  // hub pad -> Solana store: a SYNC with one leg of rent attached (v7.2)
  { name: 'ENV_PAD_TO_STORE_SYNC', src: PAD, dst: STORE, value: 2_740_000n, payload: vectors.find((v) => v.name === 'SYNC_TOKEN').hex },
  // EVM-to-EVM stays the same shape, just padded seats
  { name: 'ENV_EVM_TO_EVM', src: PAD, dst: B1, value: 0n, payload: vectors[0].hex },
]
const envelopes = ENVELOPES.map((e, i) => ({
  idx: i,
  name: e.name,
  src: e.src,
  dst: e.dst,
  value: e.value.toString(),
  payload: e.payload,
  hex: encodeEnvelope(e.src, e.dst, e.payload, e.value),
}))

// EXECUTOR OPTIONS (v7): the adapters build one type-3 lzReceive option per
// send — abi.encodePacked(uint16 3, uint8 1, uint16 17|33, uint8 1, uint128
// gas[, uint128 value]) (LayerZeroOmniMessenger._packet). The Solana program
// builds the same bytes for its sends toward the hub.
const optionBytes = (gas, value) =>
  value === 0n
    ? solidityPacked(['uint16', 'uint8', 'uint16', 'uint8', 'uint128'], [3, 1, 17, 1, gas])
    : solidityPacked(['uint16', 'uint8', 'uint16', 'uint8', 'uint128', 'uint128'], [3, 1, 33, 1, gas, value])
const options = [
  [4_600_000n, 0n],
  [4_600_000n, 200_000_000_000_000n], // one reply leg at 0.0002 ETH
  [4_600_000n, 3n * 200_000_000_000_000n], // a spawn's three legs
  [1n, (1n << 128n) - 1n],
].map(([gas, value], idx) => ({ idx, gas: gas.toString(), value: value.toString(), hex: optionBytes(gas, value) }))

const SOLANA_TESTS = path.join(__dirname, '..', '..', 'solana', 'tests')
const out = process.env.VECTORS_OUT ?? path.join(SOLANA_TESTS, 'codec-vectors-v72.gen.json')
fs.mkdirSync(path.dirname(out), { recursive: true })
fs.writeFileSync(out, JSON.stringify({ protocol: 'v7.2', ops: vectors, envelopes, options }, null, 1))
console.log(`${vectors.length} op vectors + ${envelopes.length} envelope vectors + ${options.length} option vectors → ${path.relative(process.cwd(), out)}`)

// THE HAND-WRITTEN v7.2 VECTORS, held to this coder word by word
const byHandFile = path.join(SOLANA_TESTS, 'codec-vectors-v72.json')
if (fs.existsSync(byHandFile)) {
  const byHand = JSON.parse(fs.readFileSync(byHandFile, 'utf8'))
  const words = (v) => '0x' + v.words.map((w) => w[0]).join('')
  const asValue = (t, x) => (t.startsWith('uint') ? BigInt(x) : x)
  let bad = 0
  const opHex = byHand.ops.map((v) => {
    const name = v.name
    const { types } = OPS[name]
    const values = Object.values(v.fields).map((x, i) => asValue(types[i], x))
    const mine = encodeOp(name, values)
    const ok = mine.toLowerCase() === words(v).toLowerCase()
    if (!ok) bad += 1
    console.log(`  ${ok ? '✓' : '✗'} by-hand ${name}: ${v.note ?? ''}`)
    return mine
  })
  for (const e of byHand.envelopes) {
    // a payload given by reference to an op above, inline as its fields, or as hex
    const p = e.payload
    const payload =
      p?.vector === 'ops'
        ? opHex[p.index]
        : typeof p === 'object'
          ? encodeOp(p.op, Object.entries(p).filter(([k]) => k !== 'op').map(([, x], i) => (OPS[p.op].types[i].startsWith('uint') ? BigInt(x) : x)))
          : p
    const mine = encodeEnvelope(e.src, e.dst, payload, BigInt(e.value))
    const ok = mine.toLowerCase() === words(e).toLowerCase()
    if (!ok) bad += 1
    console.log(`  ${ok ? '✓' : '✗'} by-hand envelope: ${e.name}`)
  }
  if (bad) {
    console.error(`✗ ${bad} hand-written vector(s) in ${path.relative(process.cwd(), byHandFile)} differ from the coder`)
    process.exitCode = 1
  } else {
    console.log(`✓ every hand-written v7.2 vector equals the coder's bytes (${byHand.ops.length} ops, ${byHand.envelopes.length} envelopes)`)
  }
}
